BuilderFormContainer: FC<BuilderFormContainerProps> = ({
  labels,
  onBack,
  onCancel,
  onSubmit,
  isCancelDisabled = false,
  isSubmitDisabled = false,
  isSubmitting = false,
  left,
  children,
  metadata,
  styles: containerStyles,
}) => {
  const { colors, header, cssVars } = containerStyles ?? {};

  return (
    <div
      style={{
        ...buildCssVars({
          '--bfc-bg': colors?.background,
        }),
        ...cssVars,
      }}
      className={mergeClasses(
        'flex h-full w-full flex-col overflow-y-auto',
        styles.container,
      )}
    >
      <BuilderFormHeader
        labels={labels}
        onBack={onBack}
        onCancel={onCancel}
        onSubmit={onSubmit}
        isCancelDisabled={isCancelDisabled}
        isSubmitDisabled={isSubmitDisabled}
        isSubmitting={isSubmitting}
        styles={header}
      />
      <BuilderFormBody left={left} metadata={metadata}>
        {children}
      </BuilderFormBody>
      {/*
       * At mobile widths the action pair lives in this sticky footer pinned
       * over the scrolling form instead of the header — a thumb-reachable
       * position, with the two actions splitting the row equally. It renders
       * the same `BuilderFormActions` the header holds at the desktop
       * breakpoint: CSS cannot move one instance between the top of the page
       * and the bottom, so exactly one copy is visible (and tabbable) at any
       * width. Opaque background and the elevation shadow come from
       * `styles.footer`, so scrolled content never shows through it.
       */}
      <div
        className={mergeClasses(
          'sticky bottom-0 z-10 flex items-center gap-2 p-3 desktop:hidden',
          styles.footer,
        )}
      >
        <BuilderFormActions
          labels={labels}
          onCancel={onCancel}
          onSubmit={onSubmit}
          isCancelDisabled={isCancelDisabled}
          isSubmitDisabled={isSubmitDisabled}
          isSubmitting={isSubmitting}
          buttonClassName="flex-1"
        />
      </div>
    </div>
  );
}

export interface BuilderFormContainerProps {
  /** Localized labels for the header. */
  labels: BuilderFormHeaderLabels;
  /** Called when the user activates the header's back control. */
  onBack: () => void;
  /** Called when the user activates the form's cancel action (header on desktop, sticky footer on mobile). */
  onCancel: () => void;
  /** Called when the user activates the form's submit action (header on desktop, sticky footer on mobile). */
  onSubmit: () => void;
  /** When `true`, the cancel action is disabled on both surfaces. Defaults to `false`. */
  isCancelDisabled?: boolean;
  /** When `true`, the submit action is disabled on both surfaces. Defaults to `false`. */
  isSubmitDisabled?: boolean;
  /** When `true`, the submit action shows a spinner and reports `aria-busy` on both surfaces. Defaults to `false`. */
  isSubmitting?: boolean;
  /** Body's start-edge column. Full width on mobile, a fixed-width column on desktop. */
  left?: ReactNode;
  /** Body's main column, filling the space left by `left` and `metadata`. */
  children: ReactNode;
  /** Body's end-edge column, matching `left`'s width. When omitted while `left` is set, an empty column of the same width is reserved so the main column stays optically centered. */
  metadata?: ReactNode;
  /** Style overrides. */
  styles?: BuilderFormContainerStyles;
}

export interface BuilderFormContainerStyles {
  /** Color overrides applied as CSS custom properties. */
  colors?: BuilderFormContainerColors;
  /** Style overrides forwarded to the header. */
  header?: BuilderFormHeaderStyles;
  /**
   * Arbitrary CSS custom properties applied to the container's root element,
   * so vars read anywhere in the form cascade from a single place. Merged
   * after `colors`, so they can override it.
   */
  cssVars?: CSSProperties;
}

export interface BuilderFormContainerColors {
  /** Container background. Fallback: `--bg-layer-base`. */
  background?: string;
}

export interface BuilderFormActionsLabels {
  /** Label for the cancel action. */
  cancelButtonLabel: string;
  /** Label for the submit action. */
  submitButtonLabel: string;
}

export interface BuilderFormHeaderLabels extends BuilderFormActionsLabels {
  /** Title shown next to the back control. */
  title: string;
  /** Accessible label for the back control. */
  backButtonLabel: string;
  /** Accessible name for the submit action's busy indicator, announced while `isSubmitting` is `true`. Defaults to `'Submitting'`. */
  submittingLabel?: string;
}

export interface BuilderFormHeaderStyles {
  /** Color overrides applied as CSS custom properties. */
  colors?: BuilderFormHeaderColors;
  /** Typography overrides applied to the title. */
  typography?: BuilderFormHeaderTypography;
}

export interface BuilderFormHeaderColors {
  /** Header's bottom border color. Fallback: `--stroke-tertiary`. */
  borderColor?: string;
}

export interface BuilderFormHeaderTypography {
  /** CSS class applied to the title. Defaults to `'dial-h1-text'`. */
  fontClassName?: string;
  /** Font family applied to the title. Ignored when `fontClassName` is set. */
  fontFamily?: string;
}

export interface EditorSectionColors {
