}

export interface EditorLayoutProps {
  /** Heading text rendered as `<h1>` in the header row. */
  title: string;
  /** Called when the back-arrow button is clicked. */
  onBack: () => void;
  /** Accessible label for the back-arrow button. Defaults to `'Back'`. */
