DeploymentCreationForm: FC<DeploymentCreationFormProps> = ({
  values,
  errors,
  onChange,
  onNameBlur,
  onVersionBlur,
  iconPreviewUrl,
  onAddAvatarClick,
  labels,
  styles,
  availableLocaleOptions = [],
}) => {
  const nameInputRef = useRef<HTMLInputElement>(null);
  const versionInputRef = useRef<HTMLInputElement>(null);
  const hadErrorsRef = useRef(false);

  const hasErrors = !!(errors.name || errors.version);

  /*
   * Only steal focus on the transition from no errors to some errors (a
   * submit attempt), not on every keystroke that adds/removes one field's
   * error while the user is still typing.
   */
  useEffect(() => {
    if (hasErrors && !hadErrorsRef.current) {
      const firstInvalidRef = errors.name ? nameInputRef : versionInputRef;

      firstInvalidRef.current?.focus();
    }

    hadErrorsRef.current = hasErrors;
  }, [hasErrors, errors.name, errors.version]);

  return (
    <div
      role={labels.ariaLabel ? 'group' : undefined}
      aria-label={labels.ariaLabel}
      className={mergeClasses('flex flex-col gap-4', styles?.root)}
    >
      <AddAvatar
        label={labels.iconUrl.label}
        avatarUrl={iconPreviewUrl}
        addAvatarLabel={labels.iconUrl.addAvatarLabel}
        captionText={labels.iconUrl.captionText}
        onAddAvatarClick={onAddAvatarClick}
        className={styles?.field}
      />

      <div className={mergeClasses('flex items-start gap-4', styles?.field)}>
        <Input
          id="deployment-creation-form-name"
          inputRef={nameInputRef}
          value={values.name}
          onChange={(value) => onChange({ name: value ?? '' })}
          onBlur={onNameBlur}
          labelProps={{ label: labels.name.label, required: true }}
          placeholder={labels.name.placeholder}
          error={errors.name || undefined}
          invalid={!!errors.name}
          containerClassName="min-w-0 basis-0 grow-[2]"
        />

        <Input
          id="deployment-creation-form-version"
          inputRef={versionInputRef}
          value={values.version}
          onChange={(value) => onChange({ version: value ?? '' })}
          onBlur={onVersionBlur}
          labelProps={{ label: labels.version.label }}
          placeholder={labels.version.placeholder}
          error={errors.version || undefined}
          invalid={!!errors.version}
          containerClassName="min-w-0 basis-0 grow-[1]"
        />
      </div>

      <Textarea
        id="deployment-creation-form-description"
        value={values.description}
        onChange={(value) => onChange({ description: value })}
        labelProps={{ label: labels.description.label }}
        placeholder={labels.description.placeholder}
        containerClassName={styles?.field}
        className={RESIZABLE_TEXTAREA_CLASS_NAME}
        resize={TextareaResize.Vertical}
      />

      <DeploymentLocalesField
        value={values.otherLocales}
        onChange={(otherLocales) => onChange({ otherLocales })}
        availableLocaleOptions={availableLocaleOptions}
        labels={labels.otherLocales}
        className={styles?.field}
      />

      <div className={styles?.field}>
        <TagInput
          id="deployment-creation-form-topics"
          labelProps={{ label: labels.topics.label }}
          placeholder={labels.topics.placeholder}
          value={values.topics}
          onChange={(topics) => onChange({ topics })}
          tagClassName={TAG_INPUT_TAG_CLASS_NAME}
        />
      </div>
    </div>
  );
}

DeploymentLocalesField: FC<DeploymentLocalesFieldProps> = ({
  value,
  onChange,
  availableLocaleOptions = [],
  labels,
  className,
  summaryClassName = 'dial-body-text text-secondary',
  rowLabelClassName = 'dial-tiny-lead-text text-secondary',
}) => {
  const {
    summaryLabel,
    addLabel,
    editLabel,
    popupTitle,
    addLocaleLabel,
    localeRowLabel = 'Locale',
    languageLabel,
    nameLabel,
    namePlaceholder,
    descriptionLabel,
    descriptionPlaceholder,
    deleteAriaLabel,
    cancelLabel = 'Cancel',
    saveLabel = 'Save',
  } = labels;

  const [isOpen, setIsOpen] = useState(false);
  const [draftEntries, setDraftEntries] = useState<
    DeploymentCreationFormLocaleEntry[]
  >([]);

  const nextRowIdRef = useRef(0);

  useEffect(() => {
    if (isOpen) {
      setDraftEntries(
        value.length > 0
          ? value
          : [
              createEmptyRow(
                `locale-row-${++nextRowIdRef.current}`,
                new Set(),
                availableLocaleOptions,
              ),
            ],
      );
    }
  }, [isOpen, value, availableLocaleOptions]);

  const handleOpen = (): void => setIsOpen(true);
  const handleCancel = (): void => setIsOpen(false);

  const handleSave = (): void => {
    onChange(draftEntries.filter((entry) => entry.language && entry.name));
    setIsOpen(false);
  };

  const handleAddRow = (): void => {
    const usedLanguages = new Set(
      draftEntries.map((entry) => entry.language).filter(Boolean),
    );
    setDraftEntries((prev) => [
      ...prev,
      createEmptyRow(
        `locale-row-${++nextRowIdRef.current}`,
        usedLanguages,
        availableLocaleOptions,
      ),
    ]);
  };

  const handleRowChange = (
    id: string,
    patch: Partial<Omit<DeploymentCreationFormLocaleEntry, 'id'>>,
  ): void => {
    setDraftEntries((prev) =>
      prev.map((entry) => (entry.id === id ? { ...entry, ...patch } : entry)),
    );
  };

  const handleRowDelete = (id: string): void => {
    setDraftEntries((prev) => prev.filter((entry) => entry.id !== id));
  };

  const localeLabel = (code: string): string =>
    availableLocaleOptions.find((option) => option.code === code)?.label ??
    code.toUpperCase();

  const isSaveDisabled = draftEntries.some(
    (entry) => !entry.language || !entry.name,
  );

  /*
   * With no selectable language there is nothing the popup could ever produce:
   * every row would be missing its required language, so Save would stay
   * permanently disabled with no way for the user to satisfy it. Render no
   * control at all rather than an unusable one. `value` is left untouched —
   * `onChange` never fires from here, so already-stored locales survive.
   */
  if (availableLocaleOptions.length === 0) return null;

  return (
    <div className={mergeClasses('flex items-center gap-2', className)}>
      {value.length > 0 && (
        <span className={summaryClassName}>
          {`${summaryLabel}: ${value.map((entry) => `[${localeLabel(entry.language)}]`).join(', ')}`}
        </span>
      )}
      <LinkButton
        label={value.length > 0 ? editLabel : addLabel}
        iconBefore={
          <IconPlus
            size={DIAL_ICON_SIZE.SM}
            aria-hidden
            stroke={DIAL_KIT_ICON_STROKE}
          />
        }
        className="!px-0"
        onClick={handleOpen}
      />

      <Popup
        open={isOpen}
        header={popupTitle}
        onClose={handleCancel}
        mainButtons={[
          { label: cancelLabel, onClick: handleCancel },
          {
            label: saveLabel,
            variant: ButtonVariant.Primary,
            disabled: isSaveDisabled,
            onClick: handleSave,
          },
        ]}
      >
        <div className="flex flex-col gap-8 px-6 py-3">
          {draftEntries.map((entry, index) => {
            const usedByOtherRows = new Set(
              draftEntries
                .filter((other) => other.id !== entry.id)
                .map((other) => other.language)
                .filter(Boolean),
            );

            return (
              <div key={entry.id} className="flex flex-col gap-2">
                <div className="flex items-center justify-between">
                  <span className={rowLabelClassName}>
                    {localeRowLabel} {index + 1}
                  </span>
                  <DangerIconButton
                    appearance={ButtonAppearance.Ghost}
                    size={ElementSize.Small}
                    icon={
                      <IconTrashX
                        size={DIAL_ICON_SIZE.SM}
                        aria-hidden
                        stroke={DIAL_KIT_ICON_STROKE}
                      />
                    }
                    aria-label={`${deleteAriaLabel} ${index + 1}`}
                    onClick={() => handleRowDelete(entry.id)}
                  />
                </div>

                <div
                  role="group"
                  aria-label={`${localeRowLabel} ${index + 1}`}
                  className="flex flex-col gap-5"
                >
                  <div className="flex flex-col gap-5 desktop:flex-row desktop:items-start">
                    <Select
                      id={`${entry.id}-language`}
                      labelProps={{ label: languageLabel, required: true }}
                      /* Full width when stacked; on one row, wide enough for a full BCP-47 tag ("PT-BR") plus the chevron. */
                      className="desktop:shrink-0 desktop:basis-40"
                      options={availableLocaleOptions.map((option) => ({
                        value: option.code,
                        label: option.label,
                        disabled: usedByOtherRows.has(option.code),
                      }))}
                      value={entry.language}
                      onChange={(next) =>
                        handleRowChange(entry.id, {
                          language: next as string,
                        })
                      }
                    />

                    <Input
                      id={`${entry.id}-name`}
                      containerClassName="min-w-0 flex-1"
                      required
                      value={entry.name}
                      onChange={(next) =>
                        handleRowChange(entry.id, { name: next ?? '' })
                      }
                      labelProps={{ label: nameLabel, required: true }}
                      placeholder={namePlaceholder}
                    />
                  </div>

                  <Textarea
                    id={`${entry.id}-description`}
                    className={RESIZABLE_TEXTAREA_CLASS_NAME}
                    resize={TextareaResize.Vertical}
                    value={entry.description}
                    onChange={(next) =>
                      handleRowChange(entry.id, { description: next })
                    }
                    labelProps={{ label: descriptionLabel }}
                    placeholder={descriptionPlaceholder}
                  />
                </div>
              </div>
            );
          })}
          <LinkButton
            label={addLocaleLabel}
            iconBefore={
              <IconPlus
                size={DIAL_ICON_SIZE.SM}
                aria-hidden
                stroke={DIAL_KIT_ICON_STROKE}
              />
            }
            className="self-start"
            onClick={handleAddRow}
            disabled={draftEntries.length >= availableLocaleOptions.length}
          />
        </div>
      </Popup>
    </div>
  );
}

export interface DeploymentLocalesFieldProps {
  /** Current list of additional (non-primary) locale entries. */
